draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // book
  ctx.fillStyle = '#cccccc';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2-30, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2+30, H/2+150);
  ctx.stroke();

  // applying wisdom
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Apply', W/2, H/2-120 + 50*Math.sin(t));

  // lesson life
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Lesson', W/2-70, H/2-80 + 30*Math.cos(t));
  ctx.fillText('Life', W/2+50, H/2-80 + 30*Math.cos(t));

  ctx.restore();
}
